import java.util.*;

public class Main {
    static final int MOD = 1000000007;
    static final int MAXN = 20;
    static final int N = 2001000;
    static int[] f = new int[N];
    static int[] g = new int[N];
    static int[] b = new int[N];
    static int[] mp = new int[N];
    static int[] tot = new int[MAXN];
    static ArrayList<Integer>[] v = new ArrayList[MAXN];
    static int n;

    static int pow(int a, int b) {
        long ans = 1;
        long base = a % MOD;
        while (b > 0) {
            if ((b & 1) == 1) ans = (ans * base) % MOD;
            base = (base * base) % MOD;
            b >>= 1;
        }
        return (int) ans;
    }

    static int inv(int a) {
        return pow(a, MOD - 2);
    }

    static int popcount(int x) {
        return Integer.bitCount(x);
    }

    static int ctz(int x) {
        return Integer.numberOfTrailingZeros(x);
    }

    static boolean nextPermutation(int[] a) {
        int i = a.length - 2;
        while (i >= 0 && a[i] >= a[i + 1]) i--;
        if (i < 0) return false;
        int j = a.length - 1;
        while (a[j] <= a[i]) j--;
        int tmp = a[i];
        a[i] = a[j];
        a[j] = tmp;
        int left = i + 1, right = a.length - 1;
        while (left < right) {
            tmp = a[left];
            a[left] = a[right];
            a[right] = tmp;
            left++;
            right--;
        }
        return true;
    }

    static void fwt(int[] a, int lim) {
        if (lim == 0) return;
        lim /= 2;
        for (int i = 0; i < lim; i++) {
            a[i] += a[i + lim];
            if (a[i] >= MOD) a[i] -= MOD;
        }
        fwt(a, lim);
        fwt(a, lim); // note: second call on same array? Actually original calls fwt(a,lim) and fwt(a+lim,lim). We need to pass offset.
        // But the original code uses pointer arithmetic. We'll implement with offset.
    }

    // Correct recursive FWT with offset
    static void fwt(int[] a, int lim, int offset) {
        if (lim == 0) return;
        lim /= 2;
        for (int i = 0; i < lim; i++) {
            int idx1 = offset + i;
            int idx2 = offset + i + lim;
            a[idx1] += a[idx2];
            if (a[idx1] >= MOD) a[idx1] -= MOD;
        }
        fwt(a, lim, offset);
        fwt(a, lim, offset + lim);
    }

    static void fwt2(int[] a, int lim, int offset) {
        if (lim == 0) return;
        lim /= 2;
        for (int i = 0; i < lim; i++) {
            int idx1 = offset + i;
            int idx2 = offset + i + lim;
            a[idx1] -= a[idx2];
            if (a[idx1] < 0) a[idx1] += MOD;
        }
        fwt2(a, lim, offset);
        fwt2(a, lim, offset + lim);
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        n = in.nextInt();
        int[][] a = new int[MAXN][MAXN];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                a[i][j] = in.nextInt();
                a[i][j] = (int)((long)a[i][j] * inv(100) % MOD);
                b[i * n + j] = a[i][j];
            }
        }

        for (int i = 0; i < MAXN; i++) v[i] = new ArrayList<>();
        for (int i = 0; i < (1 << n); i++) {
            int pc = popcount(i);
            v[pc].add(i);
            mp[i] = tot[pc]++;
        }

        int m = n / 2;
        int totalM = tot[m];
        int sizeM = 1 << totalM;

        // First half
        for (int i = 0; i < (1 << (m * n)); i++) {
            long p = 1;
            int[] S = new int[3];
            for (int j = 0; j < m * n; j++) {
                int bit = (i >> j) & 1;
                if (bit == 1) p = p * b[j] % MOD;
                else p = p * (MOD + 1 - b[j]) % MOD;
            }
            for (int j = 0; j < m; j++) {
                S[j] = (i >> (j * n)) & ((1 << n) - 1);
            }
            int st = 0;
            for (int mask : v[m]) {
                int[] s = new int[m];
                int cnt = 0;
                int temp = mask;
                while (temp != 0) {
                    int k = temp & -temp;
                    s[cnt++] = ctz(k);
                    temp ^= k;
                }
                Arrays.sort(s);
                do {
                    boolean ok = true;
                    for (int jj = 0; jj < m; jj++) {
                        if ((S[jj] >> s[jj] & 1) == 0) {
                            ok = false;
                            break;
                        }
                    }
                    if (ok) {
                        st |= 1 << mp[mask];
                    }
                } while (nextPermutation(s));
            }
            f[st] = (f[st] + (int)p) % MOD;
        }

        // Second half
        int M = n - m;
        int totalM2 = tot[M];
        int sizeM2 = 1 << totalM2;
        for (int i = 0; i < (1 << (M * n)); i++) {
            long p = 1;
            int[] S = new int[3];
            for (int j = 0; j < M * n; j++) {
                int bit = (i >> j) & 1;
                if (bit == 1) p = p * b[j + n * m] % MOD;
                else p = p * (MOD + 1 - b[j + n * m]) % MOD;
            }
            for (int j = 0; j < M; j++) {
                S[j] = (i >> (j * n)) & ((1 << n) - 1);
            }
            int st = 0;
            for (int mask : v[n - m]) {
                int[] s = new int[M];
                int cnt = 0;
                int temp = mask;
                while (temp != 0) {
                    int k = temp & -temp;
                    s[cnt++] = ctz(k);
                    temp ^= k;
                }
                Arrays.sort(s);
                do {
                    boolean ok = true;
                    for (int jj = 0; jj < M; jj++) {
                        if ((S[jj] >> s[jj] & 1) == 0) {
                            ok = false;
                            break;
                        }
                    }
                    if (ok) {
                        st |= 1 << mp[(~mask) & ((1 << n) - 1)];
                    }
                } while (nextPermutation(s));
            }
            g[st] = (g[st] + (int)p) % MOD;
        }

        // FWT and convolution
        fwt(f, sizeM, 0);
        fwt(g, sizeM, 0);
        for (int i = 0; i < sizeM; i++) {
            f[i] = (int)((long)f[i] * g[i] % MOD);
        }
        fwt2(f, sizeM, 0);
        int ans = 0;
        for (int i = 1; i < sizeM; i++) {
            ans = (ans + f[i]) % MOD;
        }
        System.out.println(ans);
    }
}
